if($method==='GET'&&preg_match('#^(driver-services|guide-services|travel-packages)/([^/]+)$#',$path,$m)){[$t,$j]=$catalogs[$m[1]];$s=db()->prepare("SELECT $j FROM $t WHERE id=? AND status='published'");$s->execute([$m[2]]);$r=$s->fetchColumn();if(!$r)fail(404,'NOT_FOUND','The requested resource was not found.');out(decoded($r));}
