if($method==='GET'&&preg_match('#^driver-services/([^/]+)/reviews$#',$path,$m)){$s=db()->prepare("SELECT id,rating,author_name authorName,comment,verified,created_at createdAt FROM reviews WHERE service_type='driver' AND service_id=? AND active=1 ORDER BY created_at DESC");$s->execute([$m[1]]);$items=$s->fetchAll();out(['items'=>$items],200,pagination(count($items)));}
if($method==='POST'&&$path==='auth/challenges'){$b=json_body();$channel=$b['channel']??'';$destination=trim((string)($b['destination']??''));$valid=$channel==='email'?filter_var($destination,FILTER_VALIDATE_EMAIL):($channel==='phone'&&preg_match('/^\+[1-9][0-9]{7,14}$/',$destination));if(!$valid)fail(422,'VALIDATION_ERROR','The request contains invalid data.',['destination'=>['Provide a valid email or E.164 phone number.']]);$devCode=(string)($config['auth_dev_code']??'');if($devCode==='')fail(503,'FEATURE_NOT_CONFIGURED','Email/SMS verification is not configured.');$id=uuid();$code=$devCode;$s=db()->prepare('INSERT INTO auth_challenges(id,channel,destination,code_hash,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 10 MINUTE))');$s->execute([$id,$channel,$destination,password_hash($code,PASSWORD_DEFAULT)]);$response=['challengeId'=>$id,'channel'=>$channel,'destination'=>$destination,'expiresAt'=>(new DateTimeImmutable('+10 minutes'))->format(DATE_ATOM),'resendAfterSeconds'=>60];if(getenv('APP_DEBUG')==='1')$response['developmentCode']=$code;out($response,202);}
